-- ============================================================================
-- 家教中介平台 —— 演示数据（demo seed）
-- ----------------------------------------------------------------------------
-- 这份数据全部是虚构的，用途是让管理后台与 H5 页面有内容可看、审核流程可演示：
--   * 姓名、学校、简介均为编造；
--   * 手机号统一使用 138/139 开头的保留测试号段；
--   * 身份证号一律留空（避免伪造真实证件号）。
--
-- 原库自带数据几乎是空的（t_tutor_info 仅 2 条，且姓名为 "123"），
-- 本文件只补演示数据，不修改任何业务逻辑。
--
-- 可重复执行：开头会先删除上一次导入的 demo 数据（按 create_by='demo-seed' 与
-- openid 前缀识别）。生产环境请勿导入。
--
-- 用法：mysql -u root -p --port=3307 tutor < sql/demo-seed.sql
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM `t_wx_user`             WHERE `openid` LIKE 'demo\\_openid\\_%' OR `openid` LIKE 'demo\\_parent\\_%';
-- 注意：t_tutor_qualification 没有 create_by 列，只能按 tutor_id 区间删除
DELETE FROM `t_tutor_qualification` WHERE `tutor_id` BETWEEN 1001 AND 1012;
DELETE FROM `t_student_info`        WHERE `create_by` = 'demo-seed';
DELETE FROM `t_parent_info`         WHERE `create_by` = 'demo-seed';
DELETE FROM `t_tutor_info`          WHERE `create_by` = 'demo-seed';






SET FOREIGN_KEY_CHECKS = 1;

-- 导入后自检（应得到：0=4条待审核, 1=7条已通过, 2=1条已拒绝，另有原库1条已通过）
-- SELECT audit_status, COUNT(*) FROM t_tutor_info WHERE del_flag='0' GROUP BY audit_status;
